package com.mediconnect.observability; import io.micrometer.core.instrument.*; import org.springframework.stereotype.Component; @Component public class BusinessMetrics { private final Counter lateCancellations; private final Counter circuitBreakerFallbacks; public BusinessMetrics(MeterRegistry meterRegistry){lateCancellations=Counter.builder("mediconnect.late_cancellations").description("Number of patient cancellation attempts denied inside the 24-hour window").register(meterRegistry);circuitBreakerFallbacks=Counter.builder("mediconnect.circuit_breaker_fallbacks").description("Number of OpenFDA validations completed through the manual-validation fallback").register(meterRegistry);} public void recordLateCancellation(){lateCancellations.increment();} public void recordCircuitBreakerFallback(){circuitBreakerFallbacks.increment();} }
